import { ReactNode } from 'react';
/** The annotations track slot props */
export interface AnnotationsTrackProps {
    /** Annotation marker color (hex, rgba, token). */
    color?: string;
    /** Priority of annotation. */
    priority?: number;
    /** Annotations track label (text, emoji, icon, or unicode character). */
    label?: string;
    /** Annotations markers character (letter/emoji/icon/glyph or Unicode character). */
    symbol?: ReactNode;
    /** Hide annotations track. */
    hidden?: boolean;
}
